/// The path, whether it is filled (else stroked), and its stroke width in
/// the 24-point view box, for a built-in icon name.
pub fn icon_path(name: &str) -> Option<(&'static [PathCmd], bool, f32)> {
    Some(match name {
        "close" => (CLOSE, false, 1.5),
        "chevronDown" => (CHEVRON_DOWN, false, 1.5),
        "chevronLeft" => (CHEVRON_LEFT, false, 1.5),
        "chevronRight" => (CHEVRON_RIGHT, false, 1.5),
        "chevronsLeft" => (CHEVRONS_LEFT, false, 1.5),
        "chevronsRight" => (CHEVRONS_RIGHT, false, 1.5),
        "check" => (CHECK, false, 1.5),
        "success" => (SUCCESS, true, 1.5),
        "error" => (ERROR, true, 1.5),
        "warning" => (WARNING, true, 1.5),
        "info" => (INFO, true, 1.5),
        "calendar" => (CALENDAR, false, 1.5),
        "clock" => (CLOCK, false, 1.5),
        "externalLink" => (EXTERNAL_LINK, false, 1.5),
        "menu" => (MENU, false, 2.0),
        "moreHorizontal" => (MORE_HORIZONTAL, true, 1.5),
        "search" => (SEARCH, false, 1.5),
        "upload" => (UPLOAD, false, 1.5),
        "arrowUp" => (ARROW_UP, false, 1.5),
        "arrowDown" => (ARROW_DOWN, false, 1.5),
        "arrowsUpDown" => (ARROWS_UP_DOWN, false, 1.5),
        "funnel" => (FUNNEL, false, 1.5),
        "eyeSlash" => (EYE_SLASH, false, 1.5),
        "viewColumns" => (VIEW_COLUMNS, false, 1.5),
        "copy" => (COPY, false, 1.5),
        "checkDouble" => (CHECK_DOUBLE, false, 1.5),
        "wrench" => (WRENCH, false, 1.5),
        "stop" => (STOP, true, 1.5),
        "microphone" => (MICROPHONE, false, 1.5),
        _ => return None,
    })
}

